mapper.select:

SELECT a.*
FROM activity a
WHERE a.publisher = #{friendId}
    AND NOT EXISTS (
        SELECT 1
        FROM user_block bl
        WHERE (bl.user_id = #{friendId} AND bl.block_id = #{userId})
            OR (bl.user_id = #{userId} AND bl.block_id = #{friendId})
    )
    AND NOT EXISTS (
        SELECT 1
        FROM friend_setting fs
        WHERE fs.user_id = #{friendId}
            AND fs.friend_id = #{userId}
            AND fs.get_activity = 1
    )
    AND (
        a.access_auth = 1  
        OR (
            a.access_auth = 3
            AND EXISTS (
                SELECT 1
                FROM activity_viewer aa
                WHERE aa.activity_id = a.id
                    AND aa.friend_id = #{userId}
            )
        )  
    )
    AND a.access_auth != 2
